            pScratch->vertex3 = pScratch->vertex1;
            pScratch->blendAInit = pScratch->blendA;
            pScratch->blendA2Init = pScratch->blendA2;
            pScratch->blendBInit = pScratch->blendB;
            pScratch->blendB2Init = pScratch->blendB2;
